import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

@Module({
  exports: [RedisConfigService],
  imports: [ConfigModule, AppConfigModule],
  providers: [RedisConfigService],
})
export class RedisConfigModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class RedisConfigService implements OnModuleInit {
  private readonly context: JobsLogContext = {
    method: '',
    service: RedisConfigService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get redisStoreAmr(): string {
    return this.configService.get<string>('redisAmr') ?? '';
  }

  public get redisPlantKey(): string {
    return (
      this.configService.get<string>('redisPlantKey') ?? 'quality-di-plant'
    );
  }

  // This method runs when the module is initialized
  public onModuleInit(): void {
    this.checkConfiguration();
  }

  // Validate the configuration values
  private checkConfiguration(): void {
    this.context.method = 'checkConfiguration';
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [{ key: 'redisStoreAmr', value: this.redisStoreAmr }];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required Redis configurations are properly set',
      this.context,
    );
  }
}

